/** Kinematic RHEED simulation from a crystal structure, its surface orientation, the beam energy and incidence, and the screen geometry. */
export class SimulationRheedSimClient {
  static readonly target = "simulation.rheed_sim";
  constructor(private t: LumiTransport) {}

  /** Built-in structures, then saved ones. */
  async list_structures(): Promise<StructureList> {
    return this.t.call<StructureList>(SimulationRheedSimClient.target, "list_structures", {});
  }

  /** One structure with every atom of its conventional cell. */
  async get_structure(req: StructureName): Promise<StructureInfo> {
    return this.t.call<StructureInfo>(SimulationRheedSimClient.target, "get_structure", req);
  }

  /** Keep a CIF or a manual cell under a name. It is parsed first, and not kept if it cannot be simulated. */
  async save_structure(req: SaveStructure): Promise<StructureInfo> {
    return this.t.call<StructureInfo>(SimulationRheedSimClient.target, "save_structure", req);
  }

  /** Delete a saved structure. */
  async delete_structure(req: StructureName): Promise<Ack> {
    return this.t.call<Ack>(SimulationRheedSimClient.target, "delete_structure", req);
  }

  /** Where every rod and spot lands on the screen, labelled, without the image: tens of milliseconds, for an overlay on the live camera. */
  async rheed_spots(req: RheedSimRequest): Promise<RheedSimMeta> {
    return this.t.call<RheedSimMeta>(SimulationRheedSimClient.target, "rheed_spots", req);
  }

  /** The simulated pattern as float32 in [0, 1], height x width, with the spot list. Lossless, for analysis; a browser wants simulate_rheed_jpeg. */
  async simulate_rheed(req: RheedSimRequest): Promise<Response<RheedSimMeta>> {
    return this.t.call<Response<RheedSimMeta>>(SimulationRheedSimClient.target, "simulate_rheed", req);
  }

  /** The simulated pattern as a greyscale JPEG (the body), with the spot list. */
  async simulate_rheed_jpeg(req: RheedJpegRequest): Promise<Response<RheedJpegMeta>> {
    return this.t.call<Response<RheedJpegMeta>>(SimulationRheedSimClient.target, "simulate_rheed_jpeg", req);
  }

  async getState(): Promise<RheedSimState> {
    return this.t.controlCall<RheedSimState>(SimulationRheedSimClient.target, "state");
  }
}

/** Who is on the bus, right now. Liveness comes from heartbeat expiry, not from an RPC timing out. */
export class SystemRegistryClient {
  static readonly target = "system.registry";
  constructor(private t: LumiTransport) {}

  /** system.registry.list_nodes */
  async list_nodes(): Promise<NodeList> {
    return this.t.call<NodeList>(SystemRegistryClient.target, "list_nodes", {});
  }

  /** system.registry.get_node */
  async get_node(req: NodeQuery): Promise<NodeRecord> {
    return this.t.call<NodeRecord>(SystemRegistryClient.target, "get_node", req);
  }

  /** Block until an instance of `equipment` is up. Lets a dependent node (storage) wait for its sources instead of assuming they are there. */
  async wait_for(req: WaitForNode): Promise<NodeRecord> {
    return this.t.call<NodeRecord>(SystemRegistryClient.target, "wait_for", req);
  }

  /** Subscribe to registry_event. Returns a key for unsubscribe(). */
  onRegistryEvent(handler: (meta: RegistryEvent, payload: Uint8Array) => void): string {
    return this.t.subscribe(SystemRegistryClient.target, "registry_event", handler);
  }

  unsubscribe(key: string): void {
    this.t.unsubscribe(key);
  }

  async startStreaming(): Promise<void> {
    await this.t.controlCall(SystemRegistryClient.target, "start");
  }

  async stopStreaming(): Promise<void> {
    await this.t.controlCall(SystemRegistryClient.target, "stop");
  }

  async getState(): Promise<RegistryState> {
    return this.t.controlCall<RegistryState>(SystemRegistryClient.target, "state");
  }
}

